-- Stormwind Gryphon Rider (51348): reconstructed ambient air patrols.
-- 32 per-spawn paths; six inferred formations plus 13 independent riders.
-- Requires smooth cyclic flight support (move_flag 65) and shared formation timing.
-- Path IDs 51348001..51348032 were checked unused before initial application.
-- Preserve unrelated paths 306380,306390,306440 (GUID*10 is unsafe here).
START TRANSACTION;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 51348001 AND 51348032;
-- Inherit the existing mounted appearance and addon fields on first insert.
SELECT c.`guid`, CASE c.`guid` WHEN 30556 THEN 51348001 WHEN 30557 THEN 51348002 WHEN 30558 THEN 51348003 WHEN 30559 THEN 51348004 WHEN 30560 THEN 51348005 WHEN 30561 THEN 51348006 WHEN 30569 THEN 51348007 WHEN 30613 THEN 51348008 WHEN 30614 THEN 51348009 WHEN 30624 THEN 51348010 WHEN 30625 THEN 51348011 WHEN 30636 THEN 51348012 WHEN 30637 THEN 51348013 WHEN 30638 THEN 51348014 WHEN 30639 THEN 51348015 WHEN 30640 THEN 51348016 WHEN 30641 THEN 51348017 WHEN 30642 THEN 51348018 WHEN 30644 THEN 51348019 WHEN 30657 THEN 51348020 WHEN 30664 THEN 51348021 WHEN 30717 THEN 51348022 WHEN 30719 THEN 51348023 WHEN 30721 THEN 51348024 WHEN 30722 THEN 51348025 WHEN 30854 THEN 51348026 WHEN 30957 THEN 51348027 WHEN 31055 THEN 51348028 WHEN 31083 THEN 51348029 WHEN 31093 THEN 51348030 WHEN 31094 THEN 51348031 WHEN 31390 THEN 51348032 END, a.`mount`,a.`bytes1`,a.`bytes2`,a.`emote`,a.`auras`
FROM `creature` c JOIN `creature_template_addon` a ON a.`entry`=c.`id`
WHERE c.`id`=51348 AND c.`guid` IN (30556,30557,30558,30559,30560,30561,30569,30613,30614,30624,30625,30636,30637,30638,30639,30640,30641,30642,30644,30657,30664,30717,30719,30721,30722,30854,30957,31055,31083,31093,31094,31390)
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
-- Keep all 32 default paths available; formed followers are driven by their leader.
UPDATE `creature` SET `MovementType`=2,`spawndist`=0,`currentwaypoint`=0,
`position_z`=CASE `guid` WHEN 30556 THEN 185.000 WHEN 30557 THEN 185.000 WHEN 30558 THEN 185.000 WHEN 30559 THEN 180.000 WHEN 30560 THEN 180.000 WHEN 30561 THEN 180.000 WHEN 30569 THEN 195.000 WHEN 30613 THEN 185.000 WHEN 30614 THEN 225.000 WHEN 30624 THEN 195.000 WHEN 30625 THEN 195.000 WHEN 30636 THEN 230.000 WHEN 30637 THEN 230.000 WHEN 30638 THEN 230.000 WHEN 30639 THEN 230.000 WHEN 30640 THEN 230.000 WHEN 30641 THEN 230.000 WHEN 30642 THEN 230.000 WHEN 30644 THEN 190.000 WHEN 30657 THEN 240.000 WHEN 30664 THEN 200.000 WHEN 30717 THEN 225.000 WHEN 30719 THEN 235.000 WHEN 30721 THEN 215.000 WHEN 30722 THEN 215.000 WHEN 30854 THEN 180.000 WHEN 30957 THEN 210.000 WHEN 31055 THEN 180.000 WHEN 31083 THEN 185.000 WHEN 31093 THEN 195.000 WHEN 31094 THEN 195.000 WHEN 31390 THEN 110.000 END,
`orientation`=CASE `guid` WHEN 30556 THEN 1.847982 WHEN 30557 THEN 1.847982 WHEN 30558 THEN 1.847982 WHEN 30559 THEN 5.990040 WHEN 30560 THEN 5.990040 WHEN 30561 THEN 5.990040 WHEN 30569 THEN 0.624547 WHEN 30613 THEN 0.743908 WHEN 30614 THEN 0.066682 WHEN 30624 THEN 0.141168 WHEN 30625 THEN 0.141168 WHEN 30636 THEN 6.032589 WHEN 30637 THEN 6.032589 WHEN 30638 THEN 6.032589 WHEN 30639 THEN 6.032589 WHEN 30640 THEN 6.032589 WHEN 30641 THEN 6.032589 WHEN 30642 THEN 6.032589 WHEN 30644 THEN 2.052693 WHEN 30657 THEN 3.277501 WHEN 30664 THEN 3.818321 WHEN 30717 THEN 1.916676 WHEN 30719 THEN 0.757712 WHEN 30721 THEN 4.505099 WHEN 30722 THEN 4.505099 WHEN 30854 THEN 4.533943 WHEN 30957 THEN 3.028639 WHEN 31055 THEN 6.018945 WHEN 31083 THEN 2.861661 WHEN 31093 THEN 0.748354 WHEN 31094 THEN 0.748354 WHEN 31390 THEN 5.638086 END
WHERE `id`=51348 AND `guid` IN (30556,30557,30558,30559,30560,30561,30569,30613,30614,30624,30625,30636,30637,30638,30639,30640,30641,30642,30644,30657,30664,30717,30719,30721,30722,30854,30957,31055,31083,31093,31094,31390);
-- Existing ground patrols and formations are untouched.
DELETE FROM `creature_formations` WHERE `memberGUID` IN (30556,30557,30558,30559,30560,30561,30569,30613,30614,30624,30625,30636,30637,30638,30639,30640,30641,30642,30644,30657,30664,30717,30719,30721,30722,30854,30957,31055,31083,31093,31094,31390);
COMMIT;
